            b.setPosition(9550.5, 100.5, 9550.5);
            net.minecraft.util.MovingObjectPosition mop = new net.minecraft.util.MovingObjectPosition(9550, 100, 9550, 1,
                net.minecraft.util.Vec3.createVectorHelper(9550.5, 101, 9550.5));
