            int x = 9800, y = 100, z = 9800;
            loadAround(w, x, z, 2);
            com.divinerpgextended.entity.EntityGreatCadillion b = new com.divinerpgextended.entity.EntityGreatCadillion(w);
            b.setVariant(0);
