            boolean held = te.isCanceled() && em.getEntityData().getLong(com.divinerpgextended.perk.EnderGear.PIN) > w.getTotalWorldTime() + 1;
            em.extinguish();
            em.getEntityData().setLong(com.divinerpgextended.perk.EnderGear.PIN, 0);
