            MinecraftForge.EVENT_BUS.post(ramArrow);
            hold(v, new ItemStack(net.divinerpg.utils.items.VanillaItemsWeapons.redEnderSword));
            net.minecraftforge.event.entity.living.LivingHurtEvent ramEnder = new net.minecraftforge.event.entity.living.LivingHurtEvent(wt, DamageSource.causePlayerDamage(v), 10F);
            MinecraftForge.EVENT_BUS.post(ramEnder);
            hold(v, new ItemStack(net.divinerpg.utils.items.VanillaItemsWeapons.bedrockMaul));
            net.minecraftforge.event.entity.living.LivingHurtEvent ramMaul = new net.minecraftforge.event.entity.living.LivingHurtEvent(wt, DamageSource.causePlayerDamage(v), 10F);
            MinecraftForge.EVENT_BUS.post(ramMaul);
            hold(v, null);
            boolean ram = Math.abs(ramArrow.ammount - 1.5F) < 0.01 && Math.abs(ramEnder.ammount - 20F) < 0.01 && Math.abs(ramMaul.ammount - 20F) < 0.01;
            // explosion in the lair: blocks intact, item intact, Watcher intact; to a fighter from the explosion - no more than the cap
            int ex = cx - 8, ey = F + 2, ez = cz + 3;
            w.setBlock(ex + 1, ey, ez, Blocks.netherrack);
            net.minecraft.entity.item.EntityItem loot = new net.minecraft.entity.item.EntityItem(w, ex + 0.5, ey + 0.2, ez + 0.5, new ItemStack(Items.diamond));
            w.spawnEntityInWorld(loot);
            wt.setPosition(ex + 0.5, ey, ez - 2.5);
            float hpBefore = wt.getHealth();
            w.newExplosion(null, ex + 0.5, ey + 0.5, ez + 0.5, 5F, true, true);
            net.minecraftforge.event.entity.living.LivingHurtEvent boom = new net.minecraftforge.event.entity.living.LivingHurtEvent(v, DamageSource.setExplosionSource(null), 40F);
            MinecraftForge.EVENT_BUS.post(boom);
            boolean blast = w.getBlock(ex + 1, ey, ez) == Blocks.netherrack && !loot.isDead && wt.getHealth() == hpBefore && boom.ammount <= com.divinerpgextended.boss.WatcherHunt.BLAST_CAP
                && (w.getBlock(cx + 9, F, cz + 1) == Blocks.quartz_block || w.getBlock(cx + 9, F, cz + 1) == Blocks.stained_hardened_clay);
            loot.setDead();
            w.setBlockToAir(ex + 1, ey, ez);
