                com.divinerpgextended.magic.EntityFrostShard stray = new com.divinerpgextended.magic.EntityFrostShard(w, ap, z, px, py, pz, 4F);
                strayPasses = stray.passes(cow) && !stray.passes(z) && cow.getHealth() >= cow.getMaxHealth();
